with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '乾草の車', 'ジョン・コンスタブル', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/John_Constable_-_The_Hay_Wain_%281821%29.jpg/960px-John_Constable_-_The_Hay_Wain_%281821%29.jpg', 'イギリスの風景画家コンスタブルが1821年に完成させた作品で、ロンドンのナショナル・ギャラリーが所蔵しています。故郷サフォーク州のスタウア川を、3頭の馬に牽かれた乾草車が渡る真昼の田園を描きました。左端の家は近所の農夫ウィリー・ロットのコテージです。ロイヤル・アカデミーでは買い手がつきませんでしたが、1824年のパリのサロンで金メダルを受け、フランスの画家たちに強い印象を与えました。雲の動きや水面のきらめきに注目してください。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:John_Constable_-_The_Hay_Wain_(1821).jpg'),
    (2, '相馬の古内裏', '歌川国芳', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Takiyasha_the_Witch_and_the_Skeleton_Spectre%2C_by_Utagawa_Kuniyoshi.jpg/960px-Takiyasha_the_Witch_and_the_Skeleton_Spectre%2C_by_Utagawa_Kuniyoshi.jpg', '江戸時代末期の浮世絵師・歌川国芳が弘化2〜3年（1845〜46年）ごろに描いた3枚続の錦絵です。山東京伝の読本『善知安方忠義伝』に取材し、平将門の娘・滝夜叉姫が呼び出した骸骨の妖怪が、大宅光圀に襲いかかる場面を描いています。画面いっぱいに覆いかぶさる巨大な骸骨は、西洋から伝わった解剖学の骨格図を参考にしたとされ、写実的な骨の描き方が見どころです。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Takiyasha_the_Witch_and_the_Skeleton_Spectre,_by_Utagawa_Kuniyoshi.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

